from taf.rfrl.procedures.resources.python.webui.gnb_engine import GnbEngine
from taf.rfrl.procedures.resources.python.webui.sbts_engine import SbtsEngine
from taf.rfrl.procedures.resources.python.webui.exceptions import InvalidSwVersion


class EngineFactory:

    """ Creates GnbEngine or SbtsEngine instances. """

    @staticmethod
    def create_engine(sw_stream):
        """
        Creates GnbEngine or SbtsEngine according to sw_stream
        :param sw_stream: sw stream i. e. '5G20B'
        :type sw_stream: str
        :return: GnbEngine or SbtsEngine instance
        :rtype: Engine
        """
        if sw_stream.startswith('5G'):
            return GnbEngine(sw_stream)
        elif sw_stream.startswith('SBTS'):
            return SbtsEngine(sw_stream)
        else:
            raise InvalidSwVersion("sw_stream must start with '5G' or 'SBTS'")
